#!/usr/bin/env node
// Build a single paste-ready Staff bundle.
//
// Why this exists: STAFF-PROMPT.md's own "Notes for whoever wires this up"
// requires that a real Staff deployment receive THREE files — the prompt
// itself, BACKGROUND.md, and NARRATIVES.md (that third requirement was added
// after D56 found the failure mode caused by omitting it). Asking a human to
// paste three files in the right order, minus each file's meta-commentary, is
// exactly the kind of step that gets done wrong once and then silently
// distorts every test result afterwards. This script does the assembly so the
// human step is: open dist/staff-bundle.md, select all, paste.
//
// Usage: node scripts/build-staff-bundle.mjs
// Output: dist/staff-bundle.md

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const repo = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (f) => readFileSync(join(repo, f), "utf8");

// --- 1. The system prompt itself, extracted verbatim from its fenced block ---
const promptFile = read("STAFF-PROMPT.md");
const lines = promptFile.split("\n");
const fences = lines.reduce((acc, l, i) => (l.trim() === "````" ? [...acc, i] : acc), []);
if (fences.length !== 2) {
  throw new Error(`expected exactly 2 \`\`\`\` fences in STAFF-PROMPT.md, found ${fences.length}`);
}
const prompt = lines.slice(fences[0] + 1, fences[1]).join("\n").trim();

const versionTag = (prompt.match(/ferspas57-staff-[0-9a-z-]+/) || [])[0];
if (!versionTag) throw new Error("no ferspas57-staff-* version tag found in the prompt block");

// --- 2 & 3. The two companion documents, verbatim ---
const background = read("BACKGROUND.md").trim();
const narratives = read("NARRATIVES.md").trim();

// Sanity checks the bundle would otherwise fail silently on. Each of these has
// a real failure behind it: D56's whole bug was Staff having no access to a
// narrative's actual JSON document, so a bundle that omitted the raw blocks
// would reproduce that bug while looking complete.
const rawDocs = (narratives.match(/\*\*Raw document\*\*/g) || []).length;
if (rawDocs < 3) throw new Error(`expected 3 raw narrative documents in NARRATIVES.md, found ${rawDocs}`);
if (!narratives.includes("ferspas57-narrative/v1")) throw new Error("no narrative_version literal in NARRATIVES.md");
if (/dwg7\.github\.io/.test(prompt + background + narratives)) {
  throw new Error("stale dwg7.github.io URL in bundle source — run the canonical-URL migration (D60)");
}

const bundle = `<!--
  ferspas57 Staff — paste-ready bundle. Generated by scripts/build-staff-bundle.mjs.
  Do not hand-edit: edit STAFF-PROMPT.md / BACKGROUND.md / NARRATIVES.md and rebuild.
  Prompt version: ${versionTag}
-->

You are being configured as "Staff" for a project called ferspas57. Everything
below is your configuration, in three parts:

  PART 1 — your operating instructions. Follow these.
  PART 2 — background knowledge. Consult these; they are facts, not orders.
  PART 3 — your narrative library. Select from it; never invent entries.

Read all three before answering anything.

================================================================================
PART 1 OF 3 — OPERATING INSTRUCTIONS
================================================================================

${prompt}

================================================================================
PART 2 OF 3 — BACKGROUND KNOWLEDGE
================================================================================

The following is reference material, not instructions. It tells you what FAO,
the Hand-in-Hand Initiative, GAEZ, FERSPAS and this project actually are, and
what data sits behind them. Where it conflicts with PART 1, PART 1 governs
behaviour and PART 2 governs facts.

${background}

================================================================================
PART 3 OF 3 — NARRATIVE LIBRARY
================================================================================

The following is your narrative library. Tier 1 (the curated stories, with
their raw JSON documents) is reproduced here in full and is the only tier you
can reach without code execution. Tiers 2 and 3 are described but not included
— they live in data files you can only fetch if your runtime genuinely gives
you code execution, exactly as PART 1 describes.

Each tier-1 entry's "Raw document" block is the authoritative source of that
narrative's structure and facts. When asked to translate or adapt a narrative,
work from that block, not from the prose summary above it.

${narratives}
`;

mkdirSync(join(repo, "dist"), { recursive: true });
writeFileSync(join(repo, "dist", "staff-bundle.md"), bundle);

const bytes = Buffer.byteLength(bundle, "utf8");
console.log(`dist/staff-bundle.md written`);
console.log(`  prompt version : ${versionTag}`);
console.log(`  size           : ${bytes.toLocaleString()} bytes (~${Math.round(bytes / 4 / 1000)}k tokens, rough)`);
console.log(`  raw narratives : ${rawDocs}`);
console.log(`  lines          : ${bundle.split("\n").length.toLocaleString()}`);
